/**
 * Mapbox GL–shaped facade for the Google provider.
 *
 * Primary renderer: the persistent Photorealistic 3D scene (Google3DScene +
 * CinematicDirector). Fallback (no hardware WebGL / Map3D refused): the 2D
 * hybrid google.maps.Map with the CSS-tilt chase, flagged honestly with
 * body.google-2d-fallback. diary-app.js keeps calling jumpTo / easeTo /
 * fitBounds / addLayer / setPaintProperty exactly as it does for Mapbox.
 */

import { GoogleLngLatBounds } from "./google-bounds";
import type { GoogleMapHost } from "./google-marker";
import {
  type Camera3D,
  type LngLatBoundsLike,
  type Padding,
  type TravelMode,
  metersPerPixel,
  rangeFromZoom,
  widthTier,
  zoomFromRange,
} from "./camera-math";
import { CinematicDirector, type ChaseSample } from "./cinematic-director";
import { Google3DScene, type RouteStyle } from "./google-scene3d";

type LngLat = [number, number] | { lng: number; lat: number };

type GeoJSONFeature = {
  type?: string;
  geometry?: { type?: string; coordinates?: number[][] };
};

type SourceRecord = {
  data: GeoJSONFeature | null;
  layers: Set<string>;
};

type LayerRecord = {
  id: string;
  source: string;
  type: string;
  polyline: google.maps.Polyline | null;
  visibility: "visible" | "none";
  color: string;
  opacity: number;
  weight: number;
};

type EaseOpts = {
  center?: LngLat;
  zoom?: number;
  pitch?: number;
  bearing?: number;
  padding?: number | { top?: number; bottom?: number; left?: number; right?: number };
  duration?: number;
  essential?: boolean;
};

type FitBoundsOpts = EaseOpts & {
  maxZoom?: number;
  minZoom?: number;
};

function asLngLat(input: LngLat): { lng: number; lat: number } {
  if (Array.isArray(input)) return { lng: Number(input[0]), lat: Number(input[1]) };
  return { lng: Number(input.lng), lat: Number(input.lat) };
}

function coordsFromFeature(data: GeoJSONFeature | null): google.maps.LatLngLiteral[] {
  const coords = data?.geometry?.coordinates;
  if (!Array.isArray(coords)) return [];
  return coords
    .map((c) => ({ lng: Number(c[0]), lat: Number(c[1]) }))
    .filter((c) => Number.isFinite(c.lng) && Number.isFinite(c.lat));
}

/** Mapbox interpolate expressions → a mid-range constant width. */
function resolveWidth(value: unknown, fallback = 3): number {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (Array.isArray(value) && value[0] === "interpolate") {
    const widths: number[] = [];
    for (let i = 3; i < value.length; i += 2) {
      if (typeof value[i + 1] === "number") widths.push(value[i + 1] as number);
    }
    if (widths.length) return widths[Math.floor(widths.length / 2)] || fallback;
  }
  return fallback;
}

function resolveOpacity(value: unknown, fallback = 1): number {
  if (typeof value === "number" && Number.isFinite(value)) return Math.max(0, Math.min(1, value));
  return fallback;
}

function resolveColor(value: unknown, fallback = "#38bdf8"): string {
  return typeof value === "string" && value ? value : fallback;
}

function normalizePadding(p: EaseOpts["padding"]): Padding {
  if (typeof p === "number") return { top: p, right: p, bottom: p, left: p };
  return { top: p?.top || 0, right: p?.right || 0, bottom: p?.bottom || 0, left: p?.left || 0 };
}

export type GoogleMapShimOptions = {
  container: string | HTMLElement;
  center?: LngLat;
  zoom?: number;
  pitch?: number;
  bearing?: number;
  maxPitch?: number;
  /** Force the 2D hybrid path (tests / debugging). */
  disable3D?: boolean;
};

export class GoogleMapShim {
  readonly provider = "google" as const;
  readonly __mmdGoogleHost: GoogleMapHost;
  gmap: google.maps.Map | null = null;
  maps: typeof google.maps;
  scene: Google3DScene;
  director: CinematicDirector | null = null;

  private sources = new Map<string, SourceRecord>();
  private layers = new Map<string, LayerRecord>();
  private listeners = new Map<string, Set<(...args: unknown[]) => void>>();
  private styleLoaded = false;
  private destroyed = false;
  private mode3d = false;
  private containerEl: HTMLElement;
  private wrapEl: HTMLElement;
  private initialCamera: { center: { lng: number; lat: number }; zoom: number; pitch: number; bearing: number };
  private dirtySources = new Set<string>();
  private syncScheduled = false;
  /** True when Google Vector/WebGL tilt+heading are live on the 2D fallback. */
  private vectorOk: boolean | null = null;
  private projectionOverlay: google.maps.OverlayView | null = null;
  private userReleaseTimer: number | null = null;

  constructor(g: typeof google, opts: GoogleMapShimOptions) {
    this.maps = g.maps;
    this.containerEl =
      typeof opts.container === "string"
        ? (document.getElementById(opts.container) as HTMLElement)
        : opts.container;
    if (!this.containerEl) throw new Error("Google map container not found");
    this.wrapEl = this.containerEl.parentElement || this.containerEl;
    this.initialCamera = {
      center: asLngLat(opts.center || [-109.5, 36.8]),
      zoom: opts.zoom ?? 3.85,
      pitch: opts.pitch ?? 45,
      bearing: opts.bearing ?? 0,
    };
    this.scene = new Google3DScene(this.wrapEl);
    this.__mmdGoogleHost = { gmap: null, maps: this.maps, scene: this.scene };
    // Listeners attach right after construction; boot on the next microtask.
    queueMicrotask(() => void this.init(!!opts.disable3D));
  }

  private viewport(): { width: number; height: number } {
    return {
      width: this.wrapEl.clientWidth || window.innerWidth || 1200,
      height: this.wrapEl.clientHeight || window.innerHeight || 800,
    };
  }

  /** Range for a Mapbox zoom using the scene's live field of view. */
  private rangeFor(zoom: number, lat: number): number {
    return rangeFromZoom(zoom, lat, this.viewport().height, this.scene.getFov());
  }

  private zoomFor(range: number, lat: number): number {
    return zoomFromRange(range, lat, this.viewport().height, this.scene.getFov());
  }

  private async init(disable3D: boolean): Promise<void> {
    if (this.destroyed) return;
    let ok = false;
    if (!disable3D) {
      const { center, zoom, pitch, bearing } = this.initialCamera;
      ok = await this.scene.boot({
        lat: center.lat,
        lng: center.lng,
        range: this.rangeFor(zoom, center.lat),
        tilt: Math.min(60, pitch),
        heading: bearing,
        mode: "HYBRID",
      });
    }
    if (this.destroyed) return;
    if (ok) {
      this.mode3d = true;
      document.body.classList.remove("google-2d-fallback");
      this.director = new CinematicDirector(this.scene, {
        viewport: () => this.viewport(),
        reducedMotion: () => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false,
        enableRoll: /[?&]roll=1/.test(window.location.search),
      });
      this.scene.on("gesture", () => this.onSceneGesture());
      this.scene.on("steady", (steady) => {
        if (steady) {
          this.emit("moveend");
          this.emit("zoomend");
          this.emit("rotateend");
          this.emit("pitchend");
        }
      });
      this.scene.on("animationend", () => this.emit("moveend"));
      this.styleLoaded = true;
      this.emit("load");
      this.emit("styledata");
      return;
    }
    this.initFallback2D();
  }

  /** 2D hybrid google.maps.Map — used only when the 3D scene cannot start. */
  private initFallback2D(): void {
    const { center, zoom, pitch, bearing } = this.initialCamera;
    const renderingType =
      (this.maps as { RenderingType?: { VECTOR: string } }).RenderingType?.VECTOR || "VECTOR";
    this.gmap = new this.maps.Map(this.containerEl, {
      center: { lat: center.lat, lng: center.lng },
      zoom,
      tilt: pitch,
      heading: bearing,
      mapTypeId: "hybrid",
      renderingType,
      tiltInteractionEnabled: true,
      headingInteractionEnabled: true,
      disableDefaultUI: false,
      zoomControl: true,
      mapTypeControl: false,
      streetViewControl: false,
      fullscreenControl: false,
      rotateControl: true,
      gestureHandling: "greedy",
      clickableIcons: false,
      keyboardShortcuts: true,
      isFractionalZoomEnabled: true,
    } as google.maps.MapOptions);
    this.__mmdGoogleHost.gmap = this.gmap;
    document.body.classList.add("google-2d-fallback");
    this.installProjectionHelper();

    // Sources/layers registered before boot finished get real polylines now.
    this.layers.forEach((layer) => {
      if (layer.polyline) return;
      const src = this.sources.get(layer.source);
      layer.polyline = new this.maps.Polyline({
        path: coordsFromFeature(src?.data || null),
        map: layer.visibility === "visible" ? this.gmap : null,
        strokeColor: layer.color,
        strokeOpacity: layer.opacity,
        strokeWeight: layer.weight,
        // Road polylines are dense lat/lng samples — geodesic arcs would invent chords (main #102).
        geodesic: false,
        clickable: false,
        zIndex: layer.id.includes("casing") ? 1 : layer.id.includes("core") ? 3 : 2,
      });
    });

    this.maps.event.addListenerOnce(this.gmap, "idle", () => {
      this.styleLoaded = true;
      this.refreshVectorCapability();
      this.emit("load");
      this.emit("styledata");
    });
    this.gmap.addListener("idle", () => {
      this.emit("moveend");
      this.emit("zoomend");
      this.emit("rotateend");
      this.emit("pitchend");
    });
    this.gmap.addListener("zoom_changed", () => this.emit("zoomend"));
    this.gmap.addListener("tilt_changed", () => this.emit("pitchend"));
    this.gmap.addListener("heading_changed", () => this.emit("rotateend"));
    this.gmap.addListener("renderingtype_changed", () => this.refreshVectorCapability());
  }

  private refreshVectorCapability(): void {
    if (!this.gmap) return;
    const rt = this.gmap.getRenderingType?.();
    const vector =
      rt === "VECTOR" ||
      rt === (this.maps as { RenderingType?: { VECTOR: string } }).RenderingType?.VECTOR;
    this.vectorOk = Boolean(vector);
    try {
      const id = this.gmap.getMapTypeId?.() || "";
      if (id !== "hybrid" && id !== "satellite") this.gmap.setMapTypeId("hybrid");
    } catch {
      /* ignore */
    }
  }

  private installProjectionHelper(): void {
    if (!this.gmap) return;
    class ProjHelper extends this.maps.OverlayView {
      onAdd(): void {}
      draw(): void {}
      onRemove(): void {}
    }
    this.projectionOverlay = new ProjHelper();
    this.projectionOverlay.setMap(this.gmap);
  }

  // ── Capability flags ─────────────────────────────────────────────────────

  is3D(): boolean {
    return this.mode3d && this.scene.isActive();
  }

  /** Back-compat name used by diary-app camera guards. */
  hasImmersive3D(): boolean {
    return this.is3D();
  }

  hasVectorCamera(): boolean {
    return this.is3D() || this.vectorOk === true;
  }

  sceneHost(): HTMLElement {
    return this.scene.host;
  }

  get _googleHost(): GoogleMapHost {
    return this.__mmdGoogleHost;
  }

  // ── Events ───────────────────────────────────────────────────────────────

  on(event: string, fn: (...args: unknown[]) => void): this {
    if (!this.listeners.has(event)) this.listeners.set(event, new Set());
    this.listeners.get(event)!.add(fn);
    return this;
  }

  once(event: string, fn: (...args: unknown[]) => void): this {
    const wrapped = (...args: unknown[]) => {
      this.off(event, wrapped);
      fn(...args);
    };
    return this.on(event, wrapped);
  }

  off(event: string, fn: (...args: unknown[]) => void): this {
    this.listeners.get(event)?.delete(fn);
    return this;
  }

  private emit(event: string, ...args: unknown[]): void {
    this.listeners.get(event)?.forEach((fn) => {
      try {
        fn(...args);
      } catch (err) {
        console.error(err);
      }
    });
  }

  isStyleLoaded(): boolean {
    return this.styleLoaded;
  }

  getStyle(): { layers: { id: string; type: string }[] } {
    return { layers: [] };
  }

  // ── Containers / read-only camera ────────────────────────────────────────

  getContainer(): HTMLElement {
    return this.is3D() ? this.scene.host : this.containerEl;
  }

  getCanvas(): HTMLCanvasElement {
    return (
      (this.is3D() ? this.scene.host : this.containerEl).querySelector("canvas") ||
      document.createElement("canvas")
    );
  }

  getCanvasContainer(): HTMLElement {
    return this.getContainer();
  }

  getZoom(): number {
    if (this.is3D()) {
      const cam = this.scene.getCamera();
      return this.zoomFor(cam.range, cam.lat);
    }
    return this.gmap?.getZoom() ?? 4;
  }

  getPitch(): number {
    if (this.is3D()) return this.scene.getCamera().tilt;
    return this.gmap?.getTilt?.() ?? 0;
  }

  getBearing(): number {
    if (this.is3D()) return this.scene.getCamera().heading;
    return this.gmap?.getHeading?.() ?? 0;
  }

  getCenter(): { lng: number; lat: number; toArray: () => [number, number] } {
    if (this.is3D()) {
      const cam = this.scene.getCamera();
      return { lng: cam.lng, lat: cam.lat, toArray: () => [cam.lng, cam.lat] };
    }
    const c = this.gmap?.getCenter();
    const lng = c?.lng() ?? 0;
    const lat = c?.lat() ?? 0;
    return { lng, lat, toArray: () => [lng, lat] };
  }

  /** Approximate visible bounds (untilted footprint) — enough for verify scripts. */
  getBounds(): GoogleLngLatBounds {
    const b = new GoogleLngLatBounds();
    if (this.is3D()) {
      const cam = this.scene.getCamera();
      const vp = this.viewport();
      const zoom = this.zoomFor(cam.range, cam.lat);
      const mpp = metersPerPixel(zoom, cam.lat);
      const halfH = (vp.height / 2) * mpp;
      const halfW = (vp.width / 2) * mpp;
      const dLat = halfH / 111_320;
      const dLng = halfW / (111_320 * Math.max(0.2, Math.cos((cam.lat * Math.PI) / 180)));
      b.extend([cam.lng - dLng, cam.lat - dLat]);
      b.extend([cam.lng + dLng, cam.lat + dLat]);
      return b;
    }
    const gb = this.gmap?.getBounds();
    if (gb) {
      const sw = (gb as unknown as { getSouthWest: () => google.maps.LatLng }).getSouthWest?.();
      const ne = (gb as unknown as { getNorthEast: () => google.maps.LatLng }).getNorthEast?.();
      if (sw && ne) {
        b.extend(sw);
        b.extend(ne);
      }
    }
    return b;
  }

  project(lngLat: LngLat): { x: number; y: number } {
    if (this.is3D()) return { x: 0, y: 0 }; // Map3D exposes no projection; callers treat (0,0) as "unknown"
    const c = asLngLat(lngLat);
    const proj = this.projectionOverlay?.getProjection?.();
    if (!proj) return { x: 0, y: 0 };
    const pt = proj.fromLatLngToContainerPixel(new this.maps.LatLng(c.lat, c.lng));
    return pt ? { x: pt.x, y: pt.y } : { x: 0, y: 0 };
  }

  panBy(offset: [number, number] | { x: number; y: number }, _opts?: unknown): void {
    if (this.destroyed) return;
    const dx = Array.isArray(offset) ? offset[0] : offset.x;
    const dy = Array.isArray(offset) ? offset[1] : offset.y;
    if (this.is3D()) {
      const cam = this.scene.getCamera();
      const zoom = this.zoomFor(cam.range, cam.lat);
      const mpp = metersPerPixel(zoom, cam.lat);
      const rad = (cam.heading * Math.PI) / 180;
      const east = (dx * Math.cos(rad) + dy * Math.sin(rad)) * mpp;
      const north = (-dy * Math.cos(rad) + dx * Math.sin(rad)) * mpp;
      this.scene.setCamera({
        lat: cam.lat + north / 111_320,
        lng: cam.lng + east / (111_320 * Math.max(0.2, Math.cos((cam.lat * Math.PI) / 180))),
      });
      return;
    }
    this.gmap?.panBy(dx, dy);
  }

  resize(): void {
    /* Map3D and google.maps.Map both observe their container */
  }

  stop(): void {
    if (this.is3D()) {
      this.director?.cancel();
    }
  }

  setTerrain(_opts?: unknown): void {}

  addControl(_control: unknown, _position?: string): this {
    return this;
  }

  dragPan = { enable() {}, disable() {} };
  scrollZoom = { enable() {}, disable() {} };
  boxZoom = { enable() {}, disable() {} };
  dragRotate = { enable() {}, disable() {} };
  keyboard = { enable() {}, disable() {} };
  doubleClickZoom = { enable() {}, disable() {} };
  touchZoomRotate = { enable() {}, disable() {} };
  touchPitch = { enable() {}, disable() {} };

  // ── Sources / layers ─────────────────────────────────────────────────────

  addSource(id: string, spec: { type?: string; data?: GeoJSONFeature; lineMetrics?: boolean }): this {
    this.sources.set(id, { data: spec.data || null, layers: new Set() });
    return this;
  }

  getSource(id: string): { setData: (data: GeoJSONFeature) => void } | undefined {
    const src = this.sources.get(id);
    if (!src) return undefined;
    return {
      setData: (data: GeoJSONFeature) => {
        src.data = data;
        if (this.is3D()) {
          this.markDirty(id);
          return;
        }
        const path = coordsFromFeature(data);
        src.layers.forEach((layerId) => {
          const layer = this.layers.get(layerId);
          layer?.polyline?.setPath(path);
        });
      },
    };
  }

  addLayer(layer: {
    id: string;
    type: string;
    source: string;
    layout?: Record<string, unknown>;
    paint?: Record<string, unknown>;
  }): this {
    const src = this.sources.get(layer.source);
    if (!src) return this;
    const paint = layer.paint || {};
    const layout = layer.layout || {};
    const color = resolveColor(paint["line-color"], "#38bdf8");
    const opacity = resolveOpacity(paint["line-opacity"], 1);
    const weight = resolveWidth(paint["line-width"], 3);
    const visibility = layout.visibility === "none" ? "none" : "visible";

    let polyline: google.maps.Polyline | null = null;
    if (this.gmap) {
      polyline = new this.maps.Polyline({
        path: coordsFromFeature(src.data),
        map: visibility === "visible" ? this.gmap : null,
        strokeColor: color,
        strokeOpacity: opacity,
        strokeWeight: weight,
        // Road polylines are dense lat/lng samples — geodesic arcs would invent chords (main #102).
        geodesic: false,
        clickable: false,
        zIndex: layer.id.includes("casing") ? 1 : layer.id.includes("core") ? 3 : 2,
      });
    }
    src.layers.add(layer.id);
    this.layers.set(layer.id, {
      id: layer.id,
      source: layer.source,
      type: layer.type,
      polyline,
      visibility,
      color,
      opacity,
      weight,
    });
    if (this.is3D()) this.markDirty(layer.source);
    return this;
  }

  getLayer(id: string): LayerRecord | undefined {
    return this.layers.get(id);
  }

  setPaintProperty(id: string, prop: string, value: unknown): void {
    const layer = this.layers.get(id);
    if (!layer) return;
    if (prop === "line-color") layer.color = resolveColor(value, layer.color);
    else if (prop === "line-opacity") layer.opacity = resolveOpacity(value, layer.opacity);
    else if (prop === "line-width") layer.weight = resolveWidth(value, layer.weight);
    if (this.is3D()) {
      this.markDirty(layer.source);
      return;
    }
    const pl = layer.polyline;
    if (!pl) return;
    if (prop === "line-color") pl.setOptions({ strokeColor: layer.color });
    else if (prop === "line-opacity") pl.setOptions({ strokeOpacity: layer.opacity });
    else if (prop === "line-width") pl.setOptions({ strokeWeight: layer.weight });
    else if (prop === "line-blur") {
      const blur = typeof value === "number" ? value : 0;
      if (blur > 0.5) {
        pl.setOptions({
          strokeWeight: Math.max(layer.weight, layer.weight + blur * 2.2),
          strokeOpacity: Math.min(layer.opacity, Math.max(0.18, layer.opacity * 0.45)),
        });
      }
    }
  }

  setLayoutProperty(id: string, prop: string, value: unknown): void {
    const layer = this.layers.get(id);
    if (!layer) return;
    if (prop === "visibility") {
      layer.visibility = value === "none" ? "none" : "visible";
      if (this.is3D()) this.markDirty(layer.source);
      else layer.polyline?.setMap(layer.visibility === "visible" ? this.gmap : null);
    }
  }

  removePaintProperty(_id: string, _prop: string): void {}

  moveLayer(_id: string): void {}

  /** Batch many paint/layout writes per frame into one scene update per source. */
  private markDirty(sourceId: string): void {
    this.dirtySources.add(sourceId);
    if (this.syncScheduled) return;
    this.syncScheduled = true;
    requestAnimationFrame(() => {
      this.syncScheduled = false;
      const ids = [...this.dirtySources];
      this.dirtySources.clear();
      ids.forEach((id) => this.syncSourceToScene(id));
    });
  }

  private layersOf(sourceId: string): LayerRecord[] {
    const src = this.sources.get(sourceId);
    if (!src) return [];
    return [...src.layers].map((id) => this.layers.get(id)).filter((l): l is LayerRecord => !!l);
  }

  /** Collapse the Mapbox casing/glow/core layer stack into one 3D ribbon style. */
  private routeStyleFor(sourceId: string): RouteStyle | null {
    const layers = this.layersOf(sourceId);
    if (!layers.length) return null;
    const core =
      layers.find((l) => l.id.endsWith("-core") || l.id.endsWith("-line")) ||
      layers.find((l) => !l.id.includes("casing") && !l.id.includes("glow") && !l.id.includes("halo")) ||
      layers[layers.length - 1];
    const casing = layers.find((l) => l.id.endsWith("-casing"));
    const glow = layers.find((l) => l.id.endsWith("-glow-mid"));
    const outer = layers.find((l) => l.id.endsWith("-glow-outer"));
    const visible = core.visibility !== "none" && core.opacity > 0.01 && core.weight > 0;
    const width = Math.max(2, Math.min(9, core.weight));
    const glowOn = (glow?.visibility !== "none" && (glow?.opacity || 0) > 0.3) || ((outer?.opacity || 0) > 0.4);
    let casingColor = "#0a0e14";
    let casingWidth = 0;
    let casingAlpha = 0;
    if (glowOn) {
      casingColor = (glow || outer)?.color || core.color;
      casingWidth = 3;
      casingAlpha = Math.max(glow?.opacity || 0, (outer?.opacity || 0) * 0.8) * 0.55;
    } else if (casing && casing.visibility !== "none" && casing.opacity > 0.01) {
      casingColor = casing.color;
      casingWidth = Math.max(1, Math.min(3, (casing.weight - core.weight) / 2 || 1.5));
      casingAlpha = casing.opacity;
    }
    return {
      color: core.color,
      width,
      alpha: core.opacity,
      casingColor,
      casingWidth,
      casingAlpha,
      visible,
      zIndex: sourceId === "active-trail" ? 50 : 10,
    };
  }

  private syncSourceToScene(sourceId: string): void {
    if (!this.is3D()) return;
    const src = this.sources.get(sourceId);
    if (!src) return;
    const coords = coordsFromFeature(src.data).map((c) => [c.lng, c.lat] as [number, number]);
    if (sourceId === "active-trail") {
      if (coords.length >= 2) {
        const style = this.routeStyleFor(sourceId);
        this.scene.setTrail(coords, style?.color || "#38bdf8");
      } else {
        this.scene.clearTrail();
      }
      return;
    }
    const style = this.routeStyleFor(sourceId);
    if (!style) return;
    this.scene.setRoute(sourceId, coords.length >= 2 ? coords : null, style);
  }

  // ── Camera writes ────────────────────────────────────────────────────────

  private cameraFromOpts(opts: EaseOpts): Partial<Camera3D> {
    const cam: Partial<Camera3D> = {};
    const cur = this.scene.getCamera();
    if (opts.center) {
      const c = asLngLat(opts.center);
      cam.lat = c.lat;
      cam.lng = c.lng;
    }
    if (opts.zoom != null) cam.range = this.rangeFor(opts.zoom, cam.lat ?? cur.lat);
    if (opts.pitch != null) cam.tilt = Math.max(0, Math.min(75, opts.pitch));
    if (opts.bearing != null) cam.heading = opts.bearing;
    // Bottom-heavy padding → look slightly ahead so the subject sits in the lower part of the frame.
    if (cam.lat != null && cam.lng != null && opts.padding && typeof opts.padding === "object") {
      const pad = normalizePadding(opts.padding);
      const bottomHeavy = (pad.bottom || 0) - (pad.top || 0);
      const range = cam.range ?? cur.range;
      if (Math.abs(bottomHeavy) > 40) {
        const zoom = this.zoomFor(range, cam.lat);
        const meters = (bottomHeavy / 2) * metersPerPixel(zoom, cam.lat);
        const heading = ((cam.heading ?? cur.heading) * Math.PI) / 180;
        cam.lat += (meters * Math.cos(heading)) / 111_320;
        cam.lng += (meters * Math.sin(heading)) / (111_320 * Math.max(0.2, Math.cos((cam.lat * Math.PI) / 180)));
      }
    }
    return cam;
  }

  jumpTo(opts: EaseOpts): void {
    if (this.is3D()) {
      this.director?.setCamera(this.cameraFromOpts(opts));
      return;
    }
    this.applyCamera2D(opts, false);
  }

  easeTo(opts: EaseOpts): void {
    if (this.is3D()) {
      void this.director?.flyTo(this.cameraFromOpts(opts), opts.duration ?? 600);
      return;
    }
    this.applyCamera2D(opts, true);
  }

  flyTo(opts: EaseOpts): void {
    if (this.is3D()) {
      void this.director?.flyTo(this.cameraFromOpts(opts), opts.duration ?? 1400);
      return;
    }
    this.applyCamera2D(opts, true);
  }

  private clearRasterChase(): void {
    document.body.classList.remove("google-raster-chase");
    document.documentElement.style.removeProperty("--google-chase-pitch");
    this.containerEl.style.transform = "";
  }

  private applyRasterChaseFallback(pitch?: number, zoom?: number): void {
    if (!this.gmap) return;
    const liveTilt = this.gmap.getTilt?.() ?? 0;
    const needCss = !this.vectorOk || liveTilt < 5;
    if (!needCss) {
      this.clearRasterChase();
      return;
    }
    const p = Math.max(0, Math.min(55, pitch ?? 0));
    if (p < 8) {
      this.clearRasterChase();
      return;
    }
    const z = zoom ?? this.getZoom();
    const cssPitch = z >= 14 ? Math.min(32, p * 0.48) : z >= 12 ? Math.min(38, p * 0.58) : Math.min(42, p * 0.68);
    document.body.classList.add("google-raster-chase");
    document.documentElement.style.setProperty("--google-chase-pitch", `${cssPitch.toFixed(1)}deg`);
  }

  private applyCamera2D(opts: EaseOpts, animate: boolean): void {
    if (this.destroyed || !this.gmap) return;
    let center = opts.center ? asLngLat(opts.center) : null;
    if (center && opts.padding && typeof opts.padding === "object") {
      const pad = opts.padding;
      const bottomHeavy = (pad.bottom || 0) - (pad.top || 0);
      if (Math.abs(bottomHeavy) > 40 && opts.bearing != null) {
        const meters = Math.min(900, Math.abs(bottomHeavy) * 1.8);
        const rad = ((opts.bearing || 0) * Math.PI) / 180;
        const dLat = (meters / 110540) * (bottomHeavy > 0 ? 1 : -1);
        const dLng =
          ((meters / 111320) / Math.max(0.2, Math.cos((center.lat * Math.PI) / 180))) *
          Math.sin(rad) *
          (bottomHeavy > 0 ? 1 : -1);
        center = { lat: center.lat + dLat * Math.cos(rad), lng: center.lng + dLng };
      }
    }
    try {
      const id = this.gmap.getMapTypeId?.() || "";
      if (id !== "hybrid" && id !== "satellite") this.gmap.setMapTypeId("hybrid");
    } catch {
      /* ignore */
    }
    const cam: google.maps.CameraOptions = {};
    if (center) cam.center = { lat: center.lat, lng: center.lng };
    if (opts.zoom != null) cam.zoom = opts.zoom;
    if (opts.pitch != null) cam.tilt = Math.max(0, Math.min(67.5, opts.pitch));
    if (opts.bearing != null) cam.heading = ((opts.bearing % 360) + 360) % 360;
    this.applyRasterChaseFallback(opts.pitch, opts.zoom ?? cam.zoom);
    if (animate && opts.duration && opts.duration > 180 && center) {
      this.gmap.panTo({ lat: center.lat, lng: center.lng });
      if (opts.zoom != null) this.gmap.setZoom(opts.zoom);
      if (this.vectorOk) {
        if (opts.pitch != null) this.gmap.setTilt(cam.tilt!);
        if (opts.bearing != null) this.gmap.setHeading(cam.heading!);
      }
    } else if (!this.vectorOk) {
      const flat: google.maps.CameraOptions = {};
      if (cam.center) flat.center = cam.center;
      if (cam.zoom != null) flat.zoom = cam.zoom;
      this.gmap.moveCamera(flat);
    } else {
      this.gmap.moveCamera(cam);
    }
  }

  private boundsLike(
    bounds: GoogleLngLatBounds | [[number, number], [number, number]] | { getSouth?: () => number },
  ): LngLatBoundsLike | null {
    if (bounds instanceof GoogleLngLatBounds) {
      if (bounds.isEmpty()) return null;
      return { west: bounds.getWest(), south: bounds.getSouth(), east: bounds.getEast(), north: bounds.getNorth() };
    }
    if (Array.isArray(bounds)) {
      return { west: bounds[0][0], south: bounds[0][1], east: bounds[1][0], north: bounds[1][1] };
    }
    const b = bounds as { getSouth?: () => number; getNorth?: () => number; getWest?: () => number; getEast?: () => number };
    if (typeof b.getSouth === "function" && typeof b.getNorth === "function" && b.getWest && b.getEast) {
      return { west: b.getWest(), south: b.getSouth(), east: b.getEast(), north: b.getNorth() };
    }
    return null;
  }

  fitBounds(
    bounds: GoogleLngLatBounds | [[number, number], [number, number]] | { getSouth?: () => number },
    opts: FitBoundsOpts = {},
  ): void {
    const like = this.boundsLike(bounds);
    if (!like) return;
    if (this.is3D()) {
      const midLat = (like.north + like.south) / 2;
      void this.director?.frameBounds(like, {
        tilt: opts.pitch ?? 0,
        heading: opts.bearing ?? 0,
        fovDeg: this.scene.getFov(),
        padding: normalizePadding(opts.padding ?? 40),
        durationMs: opts.duration ?? 900,
        minRange: opts.maxZoom != null ? this.rangeFor(opts.maxZoom, midLat) : undefined,
        maxRange: opts.minZoom != null ? this.rangeFor(opts.minZoom, midLat) : undefined,
      });
      return;
    }
    if (!this.gmap) return;
    const gb = new this.maps.LatLngBounds(
      { lat: like.south, lng: like.west },
      { lat: like.north, lng: like.east },
    );
    const pad = opts.padding;
    let padding: number | google.maps.Padding = 40;
    if (typeof pad === "number") padding = pad;
    else if (pad && typeof pad === "object") padding = normalizePadding(pad);
    this.gmap.fitBounds(gb, padding);
    this.maps.event.addListenerOnce(this.gmap, "idle", () => {
      if (!this.gmap) return;
      const z = this.gmap.getZoom();
      if (opts.maxZoom != null && z != null && z > opts.maxZoom) this.gmap.setZoom(opts.maxZoom);
      if (opts.pitch != null) this.gmap.setTilt(Math.max(0, Math.min(67.5, opts.pitch)));
      if (opts.bearing != null) this.gmap.setHeading(opts.bearing);
    });
  }

  // ── 3D story / watch API (diary-app feature-detects these) ───────────────

  private onSceneGesture(): void {
    if (!this.director) return;
    this.director.userGestureBegin();
    // Outside Watch nobody calls releaseUserCamera — hand the camera back after a short idle.
    if (this.userReleaseTimer != null) window.clearTimeout(this.userReleaseTimer);
    this.userReleaseTimer = window.setTimeout(() => {
      this.userReleaseTimer = null;
      this.director?.userGestureEnd();
    }, 4500);
  }

  /** Viewer stopped exploring — the director resumes from the live camera. */
  releaseUserCamera(): void {
    if (this.userReleaseTimer != null) {
      window.clearTimeout(this.userReleaseTimer);
      this.userReleaseTimer = null;
    }
    this.director?.userGestureEnd();
  }

  isUserCamera(): boolean {
    return !!this.director?.isUserControlled();
  }

  widthTier(): "phone" | "tablet" | "desktop" {
    return widthTier(this.viewport().width);
  }

  chase3d(sample: ChaseSample): void {
    this.director?.chase(sample);
  }

  dwell3d(center: { lat: number; lng: number }, key: string, kind: "charge" | "stay" | "other" = "other"): void {
    this.director?.dwell(center, key, kind);
  }

  memory3d(center: { lat: number; lng: number }, key: string): void {
    this.director?.memory(center, key);
  }

  pause3d(center: { lat: number; lng: number }): void {
    this.director?.pause(center);
  }

  resume3d(): void {
    this.director?.resume();
  }

  resetChase3d(): void {
    this.director?.resetMotion();
  }

  finale3d(
    dest: { lat: number; lng: number },
    keyframes: Array<{ lat: number; lng: number }>,
    bounds: GoogleLngLatBounds | [[number, number], [number, number]],
    frame: { pitch: number; padding?: EaseOpts["padding"]; maxZoom?: number },
  ): Promise<void> {
    const like = this.boundsLike(bounds);
    if (!this.director || !like) return Promise.resolve();
    const midLat = (like.north + like.south) / 2;
    return this.director.finale(dest, keyframes, {
      bounds: like,
      frame: {
        tilt: frame.pitch,
        heading: 0,
        fovDeg: this.scene.getFov(),
        padding: normalizePadding(frame.padding ?? 40),
        minRange: frame.maxZoom != null ? this.rangeFor(frame.maxZoom, midLat) : undefined,
      },
    });
  }

  earthIntro(
    bounds: GoogleLngLatBounds | [[number, number], [number, number]],
    frame: { pitch: number; padding?: EaseOpts["padding"]; maxZoom?: number },
  ): Promise<void> {
    const like = this.boundsLike(bounds);
    if (!this.director || !like) return Promise.resolve();
    const midLat = (like.north + like.south) / 2;
    return this.director.earthIntro(like, {
      tilt: frame.pitch,
      heading: 0,
      fovDeg: this.scene.getFov(),
      padding: normalizePadding(frame.padding ?? 40),
      minRange: frame.maxZoom != null ? this.rangeFor(frame.maxZoom, midLat) : undefined,
    });
  }

  whenSteady(timeoutMs = 4000): Promise<boolean> {
    return this.is3D() ? this.scene.whenSteady(timeoutMs) : Promise.resolve(true);
  }

  isSteady(): boolean {
    return this.is3D() ? this.scene.isSteady() : true;
  }

  /** Watch → label-free SATELLITE for a cleaner film; Atlas / focus → HYBRID labels. */
  setWatchMode(on: boolean): void {
    if (!this.is3D()) return;
    this.scene.setMode(on ? "SATELLITE" : "HYBRID");
    document.body.classList.toggle("google-3d-watch", !!on);
  }

  setVehicle3D(lng: number, lat: number, bearing: number, mode: TravelMode | "hidden"): boolean {
    if (!this.is3D()) return false;
    return this.scene.setVehicleModel(lat, lng, bearing, mode);
  }

  hideVehicle3D(): void {
    if (this.is3D()) this.scene.hideVehicleModel();
  }

  setPillars3d(points: Array<{ lat: number; lng: number; color?: string }>): void {
    if (this.is3D()) this.scene.setPillars(points);
  }

  clearPillars3d(): void {
    if (this.is3D()) this.scene.clearPillars();
  }

  drawOn3d(sourceId: string, durationMs = 1800): Promise<void> {
    if (!this.is3D()) return Promise.resolve();
    // Flush pending style writes first so the ribbon exists before the reveal starts.
    this.syncSourceToScene(sourceId);
    return this.scene.drawOn(sourceId, durationMs);
  }

  // ── Teardown ─────────────────────────────────────────────────────────────

  remove(): void {
    this.destroyed = true;
    this.clearRasterChase();
    if (this.userReleaseTimer != null) window.clearTimeout(this.userReleaseTimer);
    this.director?.cancel();
    this.director = null;
    this.scene.destroy();
    document.body.classList.remove("google-2d-fallback", "google-3d", "google-3d-watch", "vehicle-model-3d");
    if (this.projectionOverlay) {
      this.projectionOverlay.setMap(null);
      this.projectionOverlay = null;
    }
    this.layers.forEach((layer) => layer.polyline?.setMap(null));
    this.layers.clear();
    this.sources.clear();
    this.listeners.clear();
    if (this.gmap) this.maps.event.clearInstanceListeners(this.gmap);
    this.gmap = null;
    this.containerEl.innerHTML = "";
  }
}

/** No-op NavigationControl stand-in (Google uses built-in zoom / Map3D gestures). */
export class GoogleNavigationControl {
  onAdd(): HTMLElement {
    return document.createElement("div");
  }
  onRemove(): void {}
}
