import type { Trip } from "./types";

/** Trips with this many days or fewer are mapped but not listed in Journeys. */
export const MAX_SHORT_TRIP_DAYS = 3;

type TripTiming = Pick<Trip, "start" | "end" | "duration_days">;

export function tripDurationDays(trip: TripTiming): number {
  const stored = trip.duration_days;
  if (typeof stored === "number" && Number.isFinite(stored) && stored > 0) {
    return stored;
  }
  const start = trip.start;
  const end = trip.end || trip.start;
  if (!start || !end) return 1;
  const startMs = Date.parse(start);
  const endMs = Date.parse(end);
  if (!Number.isFinite(startMs) || !Number.isFinite(endMs)) return 1;
  const startDay = new Date(startMs);
  const endDay = new Date(endMs);
  startDay.setHours(0, 0, 0, 0);
  endDay.setHours(0, 0, 0, 0);
  return Math.max(1, Math.round((endDay.getTime() - startDay.getTime()) / 86_400_000) + 1);
}

/** True when a trip should appear in the journey browser / trip chrome. */
export function isJourneyTrip(trip: TripTiming): boolean {
  return tripDurationDays(trip) > MAX_SHORT_TRIP_DAYS;
}

export function filterJourneyTrips<T extends TripTiming>(trips: T[]): T[] {
  return trips.filter(isJourneyTrip);
}
